package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/**
 * The figures the screen shows — each person's claimed and due-total, the sheet's claimed-total and
 * due-total — worked out as the screen does, so a change can audit the ones it moved: one ROLLUP
 * line per person whose figures changed (a new person counts as changed), then a TOTALS line when
 * the sheet's totals changed.
 */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final People people;
    private final Claims claims;
    private final Figures figures;
    private final Rates rates;
    private final Sheets sheets;
    private final Audit audit;

    public Rollup(People people, Claims claims, Figures figures, Rates rates, Sheets sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.figures = figures;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures now. A person's due-total is the sum of their counting claims' figures (a held
     *  person's OPEN claims do not count),
     *  n/a when there is no rate today and none has a figure; the sheet's skips the n/a ones. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.onSheet(sheetId);
        Map<Long, Snapshot.PersonFigures> figuresOf = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        BigDecimal dueTotal = ZERO;
        for (Person person : people.onSheet(sheetId)) {
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            boolean any = false;
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !person.counts(claim.getStatus())) continue;
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
                if (figure != null) {
                    due = due.add(figure);
                    any = true;
                }
            }
            if (!any && rates.pct(sheetId, person.gradeOn(today), today) == null) due = null;
            figuresOf.put(person.getId(), new Snapshot.PersonFigures(person.getName(), claimed, due));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) dueTotal = dueTotal.add(due);
        }
        return new Snapshot(figuresOf, claimedTotal, dueTotal);
    }

    /** Audit the figures that moved between `before` and the sheet now. */
    public void record(String sheetId, Snapshot before, String user) {
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes the person's statement: their due-total now, the sum of their counting claims' figures
 *  with any late charges (n/a when there is no rate today and none has a figure), dated the sheet's today. Every claim
 *  of theirs that counts (not an OPEN one while they are held) is bound to the figure it has now, without its late charge; every other one is unbound. */
public class TakeStatement {
    public void take(@Val StatementRequest request, @Val Person person, Claims claims, Figures figures,
            Rates rates, Sheets sheets, People people, Out<Statement> statement) {
        Person locked = people.lock(person.getSheetId(), person.getId());
        person.setStatementCount(locked.getStatementCount());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean any = false;
        int counted = 0;
        for (Claim claim : claims.ofPerson(person.getSheetId(), person.getId())) {
            if (person.counts(claim.getStatus())) {
                BigDecimal bound = figures.figure(claim, person.gradeOn(claim.getDate()));
                // The statement binds the figure; the late charge on top keeps following today.
                BigDecimal figure = bound == null || claim.getDue() != null ? bound : bound.add(figures.charge(claim, bound));
                claim.setStated(true);
                claim.setStatedDue(bound);
                counted++;
                if (figure != null) {
                    total = total.add(figure);
                    any = true;
                }
            } else {
                claim.setStated(false);
                claim.setStatedDue(null);
            }
            claims.save(claim);
        }
        var today = sheets.today(person.getSheetId());
        BigDecimal dueTotal = !any && rates.pct(person.getSheetId(), person.gradeOn(today), today) == null ? null : total;
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(dueTotal);
        person.setStatementDate(today);
        people.saveStatement(person);
        statement.set(new Statement(dueTotal, counted, request.user()));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Closes the period, fixing its due-total as the screen shows it now: the figures of everyone's
 *  counted (OPEN or SETTLED) claims dated in it — not
 *  the OPEN ones of a held person — n/a ones skipped. A closed period cannot be
 *  closed again. Publishes the closed period. */
public class ClosePeriod {
    public void close(@Val Period period, Periods periods, Claims claims, People people, Figures figures,
            Out<ClosedPeriod> closed) throws PeriodClosedException {
        if (period.closed()) throw new PeriodClosedException("Period " + period.name() + " is already closed");
        Map<Long, Person> personOf = people.onSheet(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::getId, p -> p));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.onSheet(period.sheetId())) {
            if (!period.contains(claim.getDate())) continue;
            Person person = personOf.get(claim.getPersonId());
            if (person == null || !person.counts(claim.getStatus())) continue;
            BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
            if (figure != null) total = total.add(figure);
        }
        periods.close(period, total);
        closed.set(new ClosedPeriod(new Period(period.sheetId(), period.name(), period.from(), period.to(), true, total)));
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { dueCents, hundredths, roundTenThousandths } from '../rates/useRates';

/** Where a claim is in its life: DRAFT → OPEN → SETTLED (or, settled by a clerk over the clerk
 *  limit, OPEN → PENDING, which a steward approves to SETTLED or rejects back to OPEN), and DRAFT,
